{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/order-table.json
    The order history as a table or as cards: number, date, items, total and a status pill, with an optional pager. Axes: layout (table, cards), pager (show, hide), tone, density.
    Props (p): id, title, orders, empty, statuses, labels, layout, pager, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_orders = ($p['orders'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_statuses = ($p['statuses'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'table')}
{var $v_pager = ($p['pager'] ?? 'show')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_11}
  {if og_t(og_eq(og_len($v_orders), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'package', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_10}
      {if og_t(og_eq($v_layout, 'table'))}
        {=og_include('blocks/order-rows.latte', ['p' => ['orders' => $v_orders, 'statuses' => $v_statuses, 'labels' => $v_labels, 'density' => $v_density]])|noescape}
      {else}
        {capture $c_9}
          {foreach og_l($v_orders) as $v_o}
            {capture $c_8}
              {capture $c_7}
                {capture $c_3}
                  {capture $c_1}
                    {=og_text(og_get($v_o, ['number']))}
                  {/capture}
                  {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
                  {capture $c_2}
                    {=og_text(og_get($v_o, ['date']))}
                  {/capture}
                  {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
                {/capture}
                {=og_include('compose/Stack.latte', ['gap' => '0', 'children' => (string) $c_3])|noescape}
                {capture $c_4}
                  {=og_text(og_tpl(og_get($v_labels, ['itemsCount']), [og_get($v_o, ['items'])]))}
                {/capture}
                {=og_include('compose/Text.latte', ['size' => 'sm', 'children' => (string) $c_4])|noescape}
                {capture $c_5}
                  {=og_text(og_money(og_get($v_o, ['total']), og_get($v_o, ['currency'])))}
                {/capture}
                {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'bold', 'children' => (string) $c_5])|noescape}
                {capture $c_6}
                  {=og_text(og_at($v_statuses, og_get($v_o, ['status'])))}
                {/capture}
                {=og_include('blocks/pill.latte', ['p' => ['tone' => (og_t(og_eq(og_get($v_o, ['status']), 'paid')) ? 'green' : (og_t(og_eq(og_get($v_o, ['status']), 'shipped')) ? 'blue' : (og_t(og_eq(og_get($v_o, ['status']), 'pending')) ? 'amber' : 'gray')))], 'children' => og_markup($c_6)])|noescape}
              {/capture}
              {=og_include('compose/CardContent.latte', ['class' => 'flex flex-wrap items-center justify-between gap-4', 'children' => (string) $c_7])|noescape}
            {/capture}
            {=og_include('compose/Card.latte', ['variant' => 'default', 'children' => (string) $c_8])|noescape}
          {/foreach}
        {/capture}
        {=og_include('compose/Stack.latte', ['gap' => '4', 'align' => 'stretch', 'attrs' => og_attrs(['data-slot', 'order-cards']), 'children' => (string) $c_9])|noescape}
      {/if}
      {if og_t(og_eq($v_pager, 'show'))}
        {=og_include('blocks/pager.latte', ['p' => ['page' => 1, 'pages' => 3, 'summary' => og_tpl(og_get($v_labels, ['summary']), [1, 4, 12]), 'previousLabel' => og_get($v_labels, ['previous']), 'nextLabel' => og_get($v_labels, ['next'])]])|noescape}
      {/if}
    {/capture}
    {=og_include('compose/Stack.latte', ['gap' => '4', 'align' => 'stretch', 'children' => (string) $c_10])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_11)])|noescape}
